import { Component, OnInit, OnDestroy } from '@angular/core';
import { Router } from '@angular/router';
import { Subscription } from 'rxjs';
import { AuctionService } from '../../services/auction.service';
import { AuthService } from '../../services/auth.service';
import { WebsocketService } from '../../services/websocket.service';
import { Auction, BidUpdate } from '../../models/auction.model';

@Component({
  selector: 'app-home',
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.css']
})
export class HomeComponent implements OnInit, OnDestroy {
  auctions: Auction[] = [];
  filteredAuctions: Auction[] = [];
  isLoading = true;
  errorMessage = '';

  categories: string[] = [];
  selectedCategory = '';
  minPrice = 0;
  maxPrice = 1000000;
  priceRangeMax = 1000000;

  private timerInterval: ReturnType<typeof setInterval> | null = null;
  timerTick = 0;

  // tracks which auctionIds just received a bid update (for flash animation)
  updatedBidIds: Set<number> = new Set();

  private wsSub!: Subscription;

  constructor(
    private auctionService: AuctionService,
    public authService: AuthService,
    private wsService: WebsocketService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.loadAuctions();
    this.timerInterval = setInterval(() => { this.timerTick++; }, 1000);
    // Connect WebSocket for real-time home page updates
    this.wsService.connect();
    this.wsSub = this.wsService.messages$.subscribe((msg: BidUpdate) => {
      if (msg.type === 'AUCTION_STARTED' && msg.auctionId) {
        const auction = this.auctions.find(a => a.auctionId === msg.auctionId);
        if (auction) { auction.status = 'LIVE'; this.applyFilters(); }
      } else if (msg.type === 'AUCTION_STOPPED' && msg.auctionId) {
        const auction = this.auctions.find(a => a.auctionId === msg.auctionId);
        if (auction) { auction.status = 'ENDED'; this.applyFilters(); }
      } else if (!msg.type && msg.auctionId && msg.amount) {
        // Regular bid update
        const auction = this.auctions.find(a => a.auctionId === msg.auctionId);
        if (auction && msg.amount > auction.currentBid) {
          auction.currentBid = msg.amount;
          if (msg.highestBidder) auction.highestBidder = msg.highestBidder;
          // Flash animation
          this.updatedBidIds.add(msg.auctionId);
          setTimeout(() => { this.updatedBidIds.delete(msg.auctionId); }, 1200);
          this.applyFilters();
        }
      }
    });
  }

  loadAuctions(): void {
    this.isLoading = true;
    this.errorMessage = '';
    this.auctionService.getFeaturedAuctions().subscribe({
      next: (data: Auction[]) => {
        this.auctions = data;
        const catSet = new Set<string>();
        data.forEach(a => { if (a.product?.category?.categoryName) catSet.add(a.product.category.categoryName); });
        this.categories = Array.from(catSet);
        const prices = data.map(a => a.currentBid || a.product.startingPrice).filter(p => p > 0);
        this.priceRangeMax = prices.length > 0 ? Math.ceil(Math.max(...prices) * 2) : 1000000;
        this.maxPrice = this.priceRangeMax;
        this.applyFilters();
        this.isLoading = false;
      },
      error: (err: { status: number }) => {
        this.isLoading = false;
        this.errorMessage = err.status === 0 ? 'Cannot connect to server.' : 'Failed to load auctions.';
      }
    });
  }

  applyFilters(): void {
    this.filteredAuctions = this.auctions.filter(a => {
      const catMatch = !this.selectedCategory || a.product?.category?.categoryName === this.selectedCategory;
      const price = a.currentBid || a.product?.startingPrice || 0;
      const priceMatch = price >= this.minPrice && price <= this.maxPrice;
      return catMatch && priceMatch;
    });
  }

  resetFilters(): void {
    this.selectedCategory = '';
    this.minPrice = 0;
    this.maxPrice = this.priceRangeMax;
    this.applyFilters();
  }

  getCountdown(auction: Auction): string {
    void this.timerTick;
    if (auction.status === 'ENDED') return 'Ended';
    if (!auction.endTime || auction.status === 'CREATED') return 'Upcoming';
    const remaining = new Date(auction.endTime).getTime() - Date.now();
    if (remaining <= 0) return 'Ending...';
    const h = Math.floor(remaining / 3600000);
    const m = Math.floor((remaining % 3600000) / 60000);
    const s = Math.floor((remaining % 60000) / 1000);
    if (h > 0) return `${h}h ${m}m ${s}s`;
    if (m > 0) return `${m}m ${s}s`;
    return `${s}s`;
  }

  isJustUpdated(auctionId: number): boolean {
    return this.updatedBidIds.has(auctionId);
  }

  goToAuction(auction: Auction): void {
    if (this.authService.getRole() === 'BUYER') {
      void this.router.navigate(['/auction', auction.auctionId], { state: { auction } });
    }
  }

  get role(): string | null { return this.authService.getRole(); }

  formatCurrency(amount: number): string {
    return new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(amount);
  }

  get liveCount(): number {
    return this.auctions.filter(a => a.status === 'LIVE').length;
  }

  ngOnDestroy(): void {
    if (this.timerInterval) clearInterval(this.timerInterval);
    if (this.wsSub) this.wsSub.unsubscribe();
    // Don't disconnect WS here — auction detail also uses it
  }
}
<div class="page-wrapper">
  <div class="container">

    <!-- Hero Banner -->
    <div class="hero-banner rounded-4 p-4 p-md-5 mb-4 text-white text-center">
      <h1 class="display-5 fw-bold mb-2">
        <i class="bi bi-hammer me-2"></i>Auction Sabha
      </h1>
      <p class="lead mb-4">Discover and bid on exclusive featured auctions in real-time.</p>
      <div class="d-flex justify-content-center gap-3 flex-wrap">
        <a routerLink="/home" class="btn btn-warning btn-lg fw-semibold">
          <i class="bi bi-lightning-fill me-2"></i>Participate Now
        </a>
        <a *ngIf="role === 'SELLER'" routerLink="/submit-product" class="btn btn-outline-light btn-lg fw-semibold">
          <i class="bi bi-plus-circle me-2"></i>Sell an Item
        </a>
        <a *ngIf="role !== 'SELLER'" routerLink="/products" class="btn btn-outline-light btn-lg fw-semibold">
          <i class="bi bi-grid me-2"></i>Browse Products
        </a>
      </div>
    </div>

    <!-- Filters Row -->
    <div class="card mb-4 p-3" *ngIf="!isLoading && auctions.length > 0">
      <div class="row g-3 align-items-end">

        <!-- Category Filter -->
        <div class="col-md-4">
          <label class="form-label small fw-semibold text-muted mb-1">Category</label>
          <select class="form-select form-select-sm" [(ngModel)]="selectedCategory" (change)="applyFilters()">
            <option value="">All Categories</option>
            <option *ngFor="let cat of categories" [value]="cat">{{ cat }}</option>
          </select>
        </div>

        <!-- Price Range -->
        <div class="col-md-6">
          <label class="form-label small fw-semibold text-muted mb-1">
            Price Range: <strong>{{ formatCurrency(minPrice) }}</strong> — <strong>{{ formatCurrency(maxPrice) }}</strong>
          </label>
          <input type="range" class="form-range" [min]="0" [max]="priceRangeMax" step="100"
                 [(ngModel)]="maxPrice" (input)="applyFilters()" />
        </div>

        <!-- Reset -->
        <div class="col-md-2">
          <button class="btn btn-outline-secondary btn-sm w-100" (click)="resetFilters()">
            <i class="bi bi-x-circle me-1"></i>Reset Filters
          </button>
        </div>
      </div>
    </div>

    <!-- Section Header -->
    <div class="d-flex align-items-center justify-content-between mb-3">
      <h4 class="section-header mb-0 fw-bold">
        Featured Auctions
        <span class="badge bg-secondary ms-2 fs-6" *ngIf="filteredAuctions.length > 0">{{ filteredAuctions.length }}</span>
      </h4>
      <button class="btn btn-outline-primary btn-sm" (click)="loadAuctions()" [disabled]="isLoading">
        <i class="bi bi-arrow-clockwise me-1"></i>Refresh
      </button>
    </div>

    <!-- Loading -->
    <div class="text-center py-5" *ngIf="isLoading">
      <div class="spinner-border text-primary" role="status"></div>
      <p class="text-muted mt-3">Loading featured auctions...</p>
    </div>

    <!-- Error -->
    <div class="alert alert-danger d-flex align-items-center gap-2" *ngIf="errorMessage && !isLoading">
      <i class="bi bi-exclamation-triangle-fill"></i>
      <span>{{ errorMessage }}</span>
      <button class="btn btn-sm btn-outline-danger ms-auto" (click)="loadAuctions()">Retry</button>
    </div>

    <!-- Empty State -->
    <div class="text-center py-5" *ngIf="!isLoading && !errorMessage && filteredAuctions.length === 0">
      <i class="bi bi-calendar-x display-3 text-muted"></i>
      <p class="text-muted mt-3 fs-5">
        {{ auctions.length === 0 ? 'No featured auctions available at the moment.' : 'No auctions match your filters.' }}
      </p>
      <button *ngIf="auctions.length > 0" class="btn btn-outline-primary btn-sm" (click)="resetFilters()">Clear Filters</button>
    </div>

    <!-- Auction Cards -->
    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4" *ngIf="!isLoading && filteredAuctions.length > 0">
      <div class="col" *ngFor="let auction of filteredAuctions">
        <div class="card h-100 auction-card">

          <!-- Image -->
          <div class="position-relative">
            <img
              [src]="auction.product.imageUrl || 'https://via.placeholder.com/400x200?text=No+Image'"
              class="card-img-top"
              [alt]="auction.product.productName"
              style="height: 200px; object-fit: cover;"
              (error)="$any($event.target).src='https://via.placeholder.com/400x200?text=No+Image'"
            />
            <span class="badge position-absolute top-0 end-0 m-2 px-3 py-2" [class]="getStatusClass(auction.status)">
              <i class="bi bi-circle-fill me-1 small" *ngIf="auction.status === 'LIVE'"></i>{{ auction.status }}
            </span>
            <span class="badge bg-warning text-dark position-absolute top-0 start-0 m-2" *ngIf="auction.isFeatured">
              <i class="bi bi-star-fill me-1"></i>Featured
            </span>
          </div>

          <div class="card-body d-flex flex-column">
            <span class="badge bg-light text-dark mb-2 align-self-start">{{ auction.product.category?.categoryName }}</span>
            <h5 class="card-title fw-bold mb-1">{{ auction.product.productName }}</h5>
            <p class="card-text text-muted small mb-3" style="display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;">
              {{ auction.product.description }}
            </p>

            <div class="bid-info mt-auto">
              <div class="d-flex justify-content-between align-items-center mb-2">
                <div>
                  <p class="text-muted small mb-0">Starting Price</p>
                  <p class="fw-semibold mb-0">{{ formatCurrency(auction.product.startingPrice) }}</p>
                </div>
                <div class="text-end">
                  <p class="text-muted small mb-0">Current Bid</p>
                  <p class="fw-bold text-primary fs-5 mb-0">{{ formatCurrency(auction.currentBid) }}</p>
                </div>
              </div>

              <!-- Timer -->
              <div class="d-flex align-items-center justify-content-center mb-2 rounded py-1"
                   [ngClass]="{'bg-danger bg-opacity-10': auction.status === 'LIVE', 'bg-light': auction.status !== 'LIVE'}">
                <i class="bi me-2" [ngClass]="{'bi-clock-fill text-danger': auction.status === 'LIVE', 'bi-clock text-muted': auction.status !== 'LIVE'}"></i>
                <span class="fw-semibold small" [ngClass]="{'text-danger': auction.status === 'LIVE', 'text-muted': auction.status !== 'LIVE'}">
                  {{ getCountdown(auction) }}
                </span>
              </div>

              <!-- Highest Bidder -->
              <p class="text-muted small mb-3" *ngIf="auction.highestBidder">
                <i class="bi bi-person-check me-1"></i>Leader: <strong>{{ auction.highestBidder }}</strong>
              </p>

              <!-- Action -->
              <button *ngIf="role === 'BUYER'" class="btn btn-primary w-100 fw-semibold"
                      (click)="goToAuction(auction)" [disabled]="auction.status === 'ENDED'">
                <i class="bi bi-lightning-fill me-2"></i>
                {{ auction.status === 'LIVE' ? 'Bid Now' : auction.status === 'CREATED' ? 'View Auction' : 'Auction Ended' }}
              </button>
              <div *ngIf="role !== 'BUYER'" class="text-center text-muted small">
                <i class="bi bi-eye me-1"></i>Viewing as {{ role }}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>

  </div>
</div>
